  function resolve(node){if(node?.$ref)return {...settingsSchema.$defs[node.$ref.split('/').at(-1)],...node,$ref:undefined};return node||{};}
  function settingsFields(node,value,path=[]){return Object.entries(node.properties||{}).map(([key,raw])=>{const p=resolve(raw),next=[...path,key],id='music-setting-'+next.join('-'),v=value?.[key]??p.default??'';if(p.type==='object'&&p.properties)return `<div class="sub-fs wide"><h4>${esc(p.title||key)}</h4><div class="fields">${settingsFields(p,v,next)}</div></div>`;const kind=p.type==='array'?'json-array':fieldKind(p);let control=kind==='json-array'?`<textarea rows="3" autocomplete="off" spellcheck="false">${esc(JSON.stringify(v,null,2))}</textarea>`:kind==='bool'?`<input type="checkbox" ${v?'checked':''}>`:p.enum?`<select>${p.enum.map(o=>`<option value="${esc(o)}" ${o===v?'selected':''}>${esc(o)}</option>`).join('')}</select>`:`<input type="${kind==='number'?'number':kind==='password'?'password':'text'}" value="${kind==='password'?'':esc(v)}" ${p.minimum!==undefined?`min="${p.minimum}"`:''} ${p.maximum!==undefined?`max="${p.maximum}"`:''} step="${p.type==='integer'?'1':'any'}" autocomplete="off" spellcheck="false">`;control=control.replace(/<(input|select|textarea)/,`<$1 id="${id}" name="music.${next.join('.')}" data-music-setting="${next.join('.')}" data-kind="${kind}"`);return `<div class="field"><label for="${id}">${esc(p.title||key)}</label>${control}<div class="help">${esc(p.description||'')}${kind==='json-array'?' Enter a JSON array.':''}</div></div>`;}).join('');}
  async function loadSettings(force=false){if(settingsLoaded&&!force||settingsDirty&&!force)return;msg('musicSettingsStatus','Loading Resonance settings…');el('musicSettingsSave').disabled=true;try{const [sc,st]=await Promise.all([api('/api/settings/schema'),api('/api/settings')]);if(!sc.ok||!st.ok)throw new Error('Music settings could not be loaded. Retry after unlocking Ashvane.');settingsSchema=sc.body.schema;if(!settingsSchema.properties.music)throw new Error('This Ashvane version has no music settings. Update or restart the local dashboard.');el('musicSettingsFields').innerHTML=settingsFields(resolve(settingsSchema.properties.music),st.body.settings.music||{});settingsDirty=false;settingsLoaded=true;msg('musicSettingsStatus','These settings belong to Resonance’s local music workflow.');}catch(error){msg('musicSettingsStatus',error.message,true);}finally{el('musicSettingsSave').disabled=!settingsLoaded;}}
