  el('musicSettingsReload').onclick=async()=>{if(settingsDirty&&!await ask({title:'Discard music settings changes?',body:'Reload the saved Resonance settings and discard changes in this form.',ok:'Discard changes',danger:true}))return;settingsDirty=false;loadSettings(true);};
  el('musicSettingsForm').onsubmit=async event=>{event.preventDefault();const payload={};el('musicSettingsSave').disabled=true;try{el('musicSettingsFields').querySelectorAll('[data-music-setting][data-changed]').forEach(input=>{let value=input.dataset.kind==='bool'?input.checked:input.dataset.kind==='number'?Number(input.value):input.value;if(input.dataset.kind==='json-array'){try{value=JSON.parse(input.value);if(!Array.isArray(value))throw new Error();}catch(_){input.focus();throw new Error('Enter a valid JSON array for '+(el(input.id)?.labels?.[0]?.textContent||input.dataset.musicSetting)+'.');}}setPath(payload,input.dataset.musicSetting.split('.'),value);});const r=await api('/api/settings',{method:'PUT',json:{settings:{music:payload}}});if(!r.ok)throw new Error(typeof r.body?.detail==='string'?r.body.detail:r.body?.error||'Music settings could not be saved. Check the form and retry.');settingsDirty=false;await loadSettings(true);msg('musicSettingsStatus','Resonance settings saved.');load();}catch(error){msg('musicSettingsStatus',error.message,true);}finally{el('musicSettingsSave').disabled=false;}};
